"use client";

import { useEffect, useState } from "react";
import { useAuth } from "@/hooks/use-auth";
import { useToast } from "@/hooks/use-toast";
import { Button } from "@/components/ui/button";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Trash2, RotateCcw, AlertTriangle, Inbox } from "lucide-react";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";

type TrashedInvoice = {
  _id: string;
  id?: string;
  invoiceNo?: string;
  clientName?: string;
  client?: string;
  title?: string;
  projectTitle?: string;
  amount?: number;
  status?: string;
  deletedAt?: string;
};

export default function InvoiceTrashPage() {
  const { user } = useAuth();
  const { toast } = useToast();
  const isAdmin = user?.role === "admin";

  const [trashed, setTrashed] = useState<TrashedInvoice[]>([]);
  const [loading, setLoading] = useState(true);
  const [restoringIds, setRestoringIds] = useState<Set<string>>(new Set());
  const [deletingIds, setDeletingIds] = useState<Set<string>>(new Set());

  const fetchTrash = async () => {
    setLoading(true);
    try {
      const res = await fetch("/api/invoices/trash");
      if (!res.ok) throw new Error("Failed to load trash");
      const data = await res.json();
      setTrashed(data);
    } catch (e: any) {
      toast({ title: "Error", description: e.message, variant: "destructive" });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchTrash();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const getId = (inv: TrashedInvoice) => String(inv._id ?? inv.id ?? "");
  const getLabel = (inv: TrashedInvoice) =>
    inv.invoiceNo ?? inv.id ?? inv._id ?? "—";

  const handleRestore = async (inv: TrashedInvoice) => {
    const id = getId(inv);
    if (restoringIds.has(id)) return;
    setRestoringIds((prev) => new Set(prev).add(id));
    try {
      const res = await fetch(`/api/invoices/${id}/restore`, {
        method: "PATCH",
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err.error || "Restore failed");
      }
      setTrashed((prev) => prev.filter((i) => getId(i) !== id));
      toast({
        title: "Invoice Restored",
        description: `${getLabel(inv)} has been moved back to Invoicing.`,
      });
    } catch (e: any) {
      toast({ title: "Restore Failed", description: e.message, variant: "destructive" });
    } finally {
      setRestoringIds((prev) => {
        const next = new Set(prev);
        next.delete(id);
        return next;
      });
    }
  };

  const handlePermanentDelete = async (inv: TrashedInvoice) => {
    const id = getId(inv);
    if (deletingIds.has(id)) return;
    setDeletingIds((prev) => new Set(prev).add(id));
    try {
      const res = await fetch(`/api/invoices/${id}/restore`, {
        method: "DELETE",
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err.error || "Permanent delete failed");
      }
      setTrashed((prev) => prev.filter((i) => getId(i) !== id));
      toast({
        title: "Permanently Deleted",
        description: `${getLabel(inv)} has been permanently removed.`,
        variant: "destructive",
      });
    } catch (e: any) {
      toast({
        title: "Delete Failed",
        description: e.message,
        variant: "destructive",
      });
    } finally {
      setDeletingIds((prev) => {
        const next = new Set(prev);
        next.delete(id);
        return next;
      });
    }
  };

  if (!isAdmin) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] gap-4 text-center">
        <AlertTriangle className="w-12 h-12 text-destructive" />
        <h2 className="text-2xl font-black">Access Denied</h2>
        <p className="text-muted-foreground font-semibold">
          Only admins can access the invoice trash.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="border-b-2 border-black pb-4">
        <div className="flex items-center gap-3">
          <Trash2 className="w-7 h-7" />
          <div>
            <h1 className="text-3xl font-black tracking-tight">Invoice Trash</h1>
            <p className="text-sm text-muted-foreground font-semibold mt-0.5">
              Deleted invoices are kept here. Restore them or permanently remove
              them.
            </p>
          </div>
        </div>
      </div>

      {/* Warning banner */}
      <div className="flex items-start gap-3 border-2 border-amber-400 bg-amber-50 rounded-lg p-4">
        <AlertTriangle className="w-5 h-5 text-amber-600 mt-0.5 shrink-0" />
        <p className="text-sm font-semibold text-amber-800">
          Permanently deleted invoices <strong>cannot be recovered</strong>.
          Use&nbsp;<strong>Restore</strong> to bring an invoice back to the
          active list.
        </p>
      </div>

      {/* Table */}
      {loading ? (
        <div className="py-20 text-center text-muted-foreground font-semibold animate-pulse">
          Loading trash…
        </div>
      ) : trashed.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-24 gap-4 border-2 border-dashed border-black/20 rounded-xl">
          <Inbox className="w-14 h-14 text-muted-foreground/40" />
          <p className="text-lg font-black text-muted-foreground">
            Trash is empty
          </p>
          <p className="text-sm text-muted-foreground font-semibold">
            Deleted invoices will appear here.
          </p>
        </div>
      ) : (
        <div className="border-2 border-black rounded-xl overflow-hidden">
          <Table>
            <TableHeader className="bg-muted/60">
              <TableRow className="border-b-2 border-black">
                <TableHead className="font-black text-xs uppercase tracking-widest">
                  Invoice #
                </TableHead>
                <TableHead className="font-black text-xs uppercase tracking-widest">
                  Client
                </TableHead>
                <TableHead className="font-black text-xs uppercase tracking-widest">
                  Title
                </TableHead>
                <TableHead className="font-black text-xs uppercase tracking-widest">
                  Amount
                </TableHead>
                <TableHead className="font-black text-xs uppercase tracking-widest">
                  Status
                </TableHead>
                <TableHead className="font-black text-xs uppercase tracking-widest">
                  Deleted At
                </TableHead>
                <TableHead className="text-right font-black text-xs uppercase tracking-widest">
                  Actions
                </TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {trashed.map((inv) => {
                const id = getId(inv);
                const isRestoring = restoringIds.has(id);
                const isDeleting = deletingIds.has(id);
                return (
                  <TableRow
                    key={id}
                    className="border-b-2 border-black/10 last:border-b-0 opacity-80 hover:opacity-100 transition-opacity"
                  >
                    <TableCell className="font-bold text-sm py-3 text-muted-foreground">
                      {getLabel(inv)}
                    </TableCell>
                    <TableCell className="text-sm py-3">
                      {inv.clientName || inv.client || "—"}
                    </TableCell>
                    <TableCell className="text-sm py-3">
                      {inv.title || inv.projectTitle || "—"}
                    </TableCell>
                    <TableCell className="text-sm py-3">
                      ₹{(inv.amount ?? 0).toLocaleString()}
                    </TableCell>
                    <TableCell className="text-sm py-3">
                      <span className="text-xs font-black tracking-widest bg-muted px-2 py-0.5 rounded">
                        {inv.status ?? "—"}
                      </span>
                    </TableCell>
                    <TableCell className="text-sm py-3 text-muted-foreground">
                      {inv.deletedAt
                        ? new Date(inv.deletedAt).toLocaleDateString("en-IN", {
                            day: "2-digit",
                            month: "short",
                            year: "numeric",
                            hour: "2-digit",
                            minute: "2-digit",
                          })
                        : "—"}
                    </TableCell>
                    <TableCell className="text-right py-3">
                      <div className="flex items-center justify-end gap-2">
                        {/* Restore */}
                        <Button
                          size="sm"
                          variant="outline"
                          className="border-2 border-black font-bold gap-1.5 hover:bg-primary hover:text-primary-foreground"
                          disabled={isRestoring || isDeleting}
                          onClick={() => handleRestore(inv)}
                        >
                          <RotateCcw className="w-3.5 h-3.5" />
                          {isRestoring ? "Restoring…" : "Restore"}
                        </Button>

                        {/* Permanent delete — requires confirmation */}
                        <AlertDialog>
                          <AlertDialogTrigger asChild>
                            <Button
                              size="sm"
                              variant="destructive"
                              className="font-bold gap-1.5"
                              disabled={isRestoring || isDeleting}
                            >
                              <Trash2 className="w-3.5 h-3.5" />
                              {isDeleting ? "Deleting…" : "Delete Forever"}
                            </Button>
                          </AlertDialogTrigger>
                          <AlertDialogContent className="border-2 border-black">
                            <AlertDialogHeader>
                              <AlertDialogTitle className="font-black text-xl flex items-center gap-2">
                                <AlertTriangle className="w-5 h-5 text-destructive" />
                                Permanently Delete Invoice?
                              </AlertDialogTitle>
                              <AlertDialogDescription className="font-semibold">
                                <strong>{getLabel(inv)}</strong> will be
                                permanently removed from the database. This
                                action&nbsp;
                                <strong className="text-destructive">
                                  cannot be undone
                                </strong>
                                .
                              </AlertDialogDescription>
                            </AlertDialogHeader>
                            <AlertDialogFooter>
                              <AlertDialogCancel className="border-2 border-black font-bold">
                                Cancel
                              </AlertDialogCancel>
                              <AlertDialogAction
                                className="bg-destructive text-destructive-foreground font-bold hover:bg-destructive/90"
                                onClick={() => handlePermanentDelete(inv)}
                              >
                                Yes, Delete Forever
                              </AlertDialogAction>
                            </AlertDialogFooter>
                          </AlertDialogContent>
                        </AlertDialog>
                      </div>
                    </TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        </div>
      )}

      <p className="text-xs text-muted-foreground font-semibold text-right">
        {trashed.length} invoice{trashed.length !== 1 ? "s" : ""} in trash
      </p>
    </div>
  );
}
